cypress_script:
describe('Keyboard Input Feedback', () => {
  it('should display the correct key when a key is pressed', () => {
    cy.visit('https://the-internet.herokuapp.com/key_presses');
    cy.get('#target').type('A');
    cy.get('#result').should('be.visible');
  });

  it('should not change the URL when a key is pressed', () => {
    cy.visit('https://the-internet.herokuapp.com/key_presses');
    cy.get('#target').type('A');
    cy.url().should('eq', 'https://the-internet.herokuapp.com/key_presses');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Keyboard Input Feedback', () => {
  test('should display the correct key when a key is pressed', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/key_presses');
    await page.fill('#target', 'A');
    const resultVisible = await page.isVisible('#result');
    expect(resultVisible).toBe(true);
  });

  test('should not change the URL when a key is pressed', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/key_presses');
    await page.fill('#target', 'A');
    expect(page.url()).toBe('https://the-internet.herokuapp.com/key_presses');
  });
});
